/**
 * Smart EoD defaults + transcription-error detection.
 *
 * Given the last N days of derived-margin snapshots plus today's recorded
 * fuel delivery, compute:
 *   - expected opening inventory  =  yesterday EOD inv + today delivery
 *   - suggested EOD inventory     =  opening - today's Bulloch volume
 *   - 30-day moving averages for sales $ and volume L
 *
 * Each helper is a pure function so it can be unit-tested separately from
 * React.
 */
import {
  netSellPricePerL,
  rollingAvgCost as rollingAvgCostFn,
  type TaxConfig,
} from "./math/cost";
import type { DerivedMarginFile, FuelDeliveriesFile } from "./types";

/**
 * Live margin preview computed from in-flight EoD form values, the most
 * recent rolling-average cost (from yesterday's snapshot), the day's recorded
 * delivery, and the configured tax constants.
 *
 * The math mirrors src/lib/math/cost.ts exactly so the preview matches what
 * will be persisted by recomputeAndSaveMargin().
 */
export interface LiveMargin {
  /** Avg pump price $/L = todaySalesCAD / todayVolumeL (or 0). */
  avgPumpPrice: number;
  /** Tax-stripped net sell $/L per the configured taxes. */
  netSellPrice: number;
  /** Rolling-average product cost $/L after applying any today delivery. */
  rollingAvgCost: number;
  /** Associate margin $/L (netSell - rollingAvgCost). */
  marginPerL: number;
  /** Today's gross profit $. */
  grossProfit: number;
}

export interface ComputeLiveMarginArgs {
  todaySalesCAD: number;
  todayVolumeL: number;
  /** Yesterday's EOD rolling-avg cost (from the most recent derived margin snapshot). */
  prevRollingAvgCost: number;
  /** Yesterday's EOD inventory L (needed if today has a delivery). */
  prevInventoryL: number;
  /** Sum of today's delivery purchase volumes for this grade. */
  todayDeliveryL: number;
  /** Weighted product+delivery cost $/L for today's delivery (0 if no delivery). */
  todayDeliveryUnitCost: number;
  tax: TaxConfig;
}

export function computeLiveMargin(args: ComputeLiveMarginArgs): LiveMargin {
  const avgPump =
    args.todayVolumeL > 0 ? args.todaySalesCAD / args.todayVolumeL : 0;
  const netSell = avgPump > 0 ? netSellPricePerL(avgPump, args.tax) : 0;
  const rolling = rollingAvgCostFn(
    args.prevInventoryL,
    args.prevRollingAvgCost,
    args.todayDeliveryL,
    args.todayDeliveryUnitCost,
  );
  const margin = avgPump > 0 ? netSell - rolling : 0;
  const gp = margin * (args.todayVolumeL || 0);
  return {
    avgPumpPrice: avgPump,
    netSellPrice: netSell,
    rollingAvgCost: rolling,
    marginPerL: margin,
    grossProfit: gp,
  };
}

export interface GradeHistoryStats {
  /** Number of past days that actually had sales for this grade. */
  daysWithSales: number;
  /** Mean Bulloch sales $ across days with sales. */
  avgSalesCAD: number;
  /** Mean Bulloch volume L across days with sales. */
  avgVolumeL: number;
  /** Sample std-dev of volume (population variance, sample n-1). */
  volumeStdL: number;
  /** Yesterday's EOD inventory in L (most recent snapshot). */
  yesterdayEodInvL?: number;
  /** Yesterday's rolling-avg product cost $/L (most recent snapshot). */
  yesterdayRollingAvgCost?: number;
  /** Today's recorded delivery for this grade (sum across multiple deliveries). */
  todayDeliveryL: number;
  /** Weighted unit cost $/L (product + delivery) for today's deliveries. */
  todayDeliveryUnitCost: number;
}

export function computeHistoryStats(opts: {
  gradeId: string;
  pastMargins: DerivedMarginFile[];
  todayDelivery: FuelDeliveriesFile | null;
}): GradeHistoryStats {
  let daysWithSales = 0;
  let totalSales = 0;
  let totalVolume = 0;
  const volumes: number[] = [];
  let yesterdayEodInvL: number | undefined;
  let yesterdayRollingAvgCost: number | undefined;
  let mostRecentDate: string | undefined;

  for (const m of opts.pastMargins) {
    const row = m.rows.find((r) => r.gradeId === opts.gradeId);
    if (!row) continue;
    if (!mostRecentDate || m.date > mostRecentDate) {
      mostRecentDate = m.date;
      yesterdayEodInvL = row.eodInventoryL;
      yesterdayRollingAvgCost = row.rollingAvgCost;
    }
    if (row.hasSales && row.bullochVolumeL > 0) {
      daysWithSales += 1;
      totalSales += row.bullochSalesCAD;
      totalVolume += row.bullochVolumeL;
      volumes.push(row.bullochVolumeL);
    }
  }

  const avgVolumeL = daysWithSales > 0 ? totalVolume / daysWithSales : 0;
  let varianceSum = 0;
  for (const v of volumes) {
    const d = v - avgVolumeL;
    varianceSum += d * d;
  }
  const volumeStdL =
    volumes.length > 1 ? Math.sqrt(varianceSum / (volumes.length - 1)) : 0;

  // Aggregate today's deliveries for this grade: total L and weighted unit cost
  const todayEntries = (opts.todayDelivery?.entries ?? []).filter(
    (e) => e.gradeId === opts.gradeId,
  );
  const todayDeliveryL = todayEntries.reduce((s, e) => s + e.purchaseVolumeL, 0);
  const todayDeliveryUnitCost =
    todayDeliveryL > 0
      ? todayEntries.reduce(
          (s, e) => s + e.purchaseVolumeL * (e.productCostExTaxPerL + e.deliveryCostPerL),
          0,
        ) / todayDeliveryL
      : 0;

  return {
    daysWithSales,
    avgSalesCAD: daysWithSales > 0 ? totalSales / daysWithSales : 0,
    avgVolumeL,
    volumeStdL,
    yesterdayEodInvL,
    yesterdayRollingAvgCost,
    todayDeliveryL,
    todayDeliveryUnitCost,
  };
}

export interface GradeSuggestion {
  /** Inventory at the *start* of today before sales: yesterday EOD + today delivery. */
  openingInventoryL?: number;
  /** Suggested EOD inv if Bulloch volume is known: opening - todayVolume. */
  suggestedEodInvL?: number;
}

export function computeSuggestion(
  stats: GradeHistoryStats,
  todayBullochVolumeL: number,
): GradeSuggestion {
  if (stats.yesterdayEodInvL == null) return {};
  const opening = stats.yesterdayEodInvL + stats.todayDeliveryL;
  const suggestedEod =
    todayBullochVolumeL > 0 ? Math.max(0, opening - todayBullochVolumeL) : undefined;
  return { openingInventoryL: opening, suggestedEodInvL: suggestedEod };
}

export type VerifyLevel = "ok" | "warn" | "alarm";

export interface VerifyResult {
  level: VerifyLevel;
  reason?: string;
}

/**
 * Compare today's entry against the rolling 30-day stats for this grade and
 * flag obvious typos or pump-skim signals.
 *
 * Heuristics (intentionally conservative so we don't cry wolf):
 *   - alarm: today's sales $ implies a pump price of <$0.50/L or >$3.00/L
 *   - alarm: today's volume is > 3 standard deviations from the mean
 *   - warn:  today's volume is > 2 standard deviations from the mean
 *   - warn:  ratio sales/volume differs from the 30-day average by > 8%
 */
export function verifyEntry(opts: {
  todaySalesCAD: number;
  todayVolumeL: number;
  stats: GradeHistoryStats;
}): VerifyResult {
  const { todaySalesCAD, todayVolumeL, stats } = opts;
  if (todayVolumeL <= 0 || todaySalesCAD <= 0) return { level: "ok" };
  const pumpToday = todaySalesCAD / todayVolumeL;
  if (pumpToday < 0.5 || pumpToday > 3) {
    return {
      level: "alarm",
      reason: `Pump price $${pumpToday.toFixed(2)}/L is outside the $0.50-$3.00 sanity band.`,
    };
  }
  if (stats.daysWithSales < 5) return { level: "ok" }; // not enough history

  if (stats.volumeStdL > 0) {
    const z = Math.abs(todayVolumeL - stats.avgVolumeL) / stats.volumeStdL;
    if (z > 3) {
      return {
        level: "alarm",
        reason: `Volume ${todayVolumeL.toFixed(0)} L is ${z.toFixed(1)}sd from the 30-day mean of ${stats.avgVolumeL.toFixed(0)} L.`,
      };
    }
    if (z > 2) {
      return {
        level: "warn",
        reason: `Volume ${todayVolumeL.toFixed(0)} L deviates ${z.toFixed(1)}sd from the 30-day mean of ${stats.avgVolumeL.toFixed(0)} L.`,
      };
    }
  }

  const pumpHistorical = stats.avgVolumeL > 0 ? stats.avgSalesCAD / stats.avgVolumeL : 0;
  if (pumpHistorical > 0) {
    const pct = Math.abs(pumpToday - pumpHistorical) / pumpHistorical;
    if (pct > 0.08) {
      return {
        level: "warn",
        reason: `Avg pump price $${pumpToday.toFixed(3)}/L differs ${(pct * 100).toFixed(1)}% from the 30-day average of $${pumpHistorical.toFixed(3)}/L.`,
      };
    }
  }
  return { level: "ok" };
}
