import React from "react";
import ReactDOM from "react-dom/client";
import { BrowserRouter } from "react-router-dom";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { Toaster } from "sonner";

import App from "@/app/App";
import { ErrorBoundary } from "@/components/ErrorBoundary";
import { useTheme } from "@/lib/theme-store";
import "@/index.css";

useTheme.getState().initialize();

function ThemedToaster() {
  const effective = useTheme((s) => s.effective);
  return <Toaster richColors closeButton position="top-right" theme={effective} />;
}

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: 30_000,
      refetchOnWindowFocus: false,
      retry: 1,
    },
  },
});

// Vite BASE_URL is "/" for root deploy, or "/subdir/" for GitHub Pages subpath.
// React Router basename must be undefined at site root — never pass "/".
const rawBase = import.meta.env.BASE_URL ?? "/";
const trimmed = rawBase.replace(/\/$/, "");
const basename = trimmed === "" ? undefined : trimmed;

ReactDOM.createRoot(document.getElementById("root")!).render(
  <React.StrictMode>
    <ErrorBoundary>
      <QueryClientProvider client={queryClient}>
        <BrowserRouter basename={basename}>
          <App />
          <ThemedToaster />
        </BrowserRouter>
      </QueryClientProvider>
    </ErrorBoundary>
  </React.StrictMode>,
);
