/**
 * Three-way theme toggle for the sidebar.
 *
 * Cycles light -> dark -> system. The current mode is shown by the active
 * button. We use a button group rather than a single icon so the chosen
 * mode is always visible (especially "System" which differs from light/dark
 * in subtle ways).
 */
import { Moon, MonitorSmartphone, Sun } from "lucide-react";

import { Button } from "@/components/ui/button";
import { useTheme, type ThemeMode } from "@/lib/theme-store";
import { cn } from "@/lib/utils";

const OPTIONS: Array<{ id: ThemeMode; label: string; icon: typeof Sun }> = [
  { id: "light", label: "Light", icon: Sun },
  { id: "dark", label: "Dark", icon: Moon },
  { id: "system", label: "System", icon: MonitorSmartphone },
];

export function ThemeToggle({ compact = false }: { compact?: boolean }) {
  const mode = useTheme((s) => s.mode);
  const setMode = useTheme((s) => s.setMode);
  return (
    <div className="inline-flex items-center gap-0.5 rounded-md border bg-card/60 p-0.5">
      {OPTIONS.map((opt) => {
        const Active = mode === opt.id;
        return (
          <Button
            key={opt.id}
            variant="ghost"
            size="sm"
            onClick={() => setMode(opt.id)}
            title={opt.label}
            className={cn(
              "h-7 gap-1.5 px-2 text-xs",
              Active ? "bg-secondary text-foreground" : "text-muted-foreground",
            )}
          >
            <opt.icon className="h-3.5 w-3.5" />
            {!compact ? <span>{opt.label}</span> : null}
          </Button>
        );
      })}
    </div>
  );
}
