/**
 * Scan-to-fill for the EOD report. The cashier photographs the Bulloch tape
 * (or deposit slip), the Worker asks Gemini vision for a structured
 * extraction, and every value found is shown next to what's currently in the
 * form. Nothing is applied silently — the human approves the batch, and the
 * photo is auto-attached as the day's receipt for audit.
 *
 * If the Worker has no GEMINI_API_KEY the endpoint answers 501 and this card
 * hides itself.
 */
import { useEffect, useState } from "react";
import { AlertTriangle, Check, Loader2, ScanLine, X } from "lucide-react";
import { toast } from "sonner";

import { ApiError, api } from "@/lib/api";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import type { FuelGrade, ReceiptAttachment, SalesFile, ScanResult } from "@/lib/types";

const MAX_WIDTH_PX = 1600; // slightly higher than receipt attachments — OCR needs legible digits
const JPEG_QUALITY = 0.85;

async function toScanDataUrl(file: File): Promise<string> {
  const bitmap = await createImageBitmap(file).catch(() => null);
  if (!bitmap) throw new Error("Could not read the image");
  const ratio = Math.min(1, MAX_WIDTH_PX / Math.max(bitmap.width, 1));
  const canvas = document.createElement("canvas");
  canvas.width = Math.round(bitmap.width * ratio);
  canvas.height = Math.round(bitmap.height * ratio);
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("Canvas unavailable");
  ctx.drawImage(bitmap, 0, 0, canvas.width, canvas.height);
  return canvas.toDataURL("image/jpeg", JPEG_QUALITY);
}

interface ExtractedRow {
  key: string;
  label: string;
  scanned: number;
  current: number | undefined;
  apply: (s: SalesFile) => SalesFile;
}

function collectRows(result: ScanResult, sales: SalesFile, grades: FuelGrade[]): ExtractedRow[] {
  const rows: ExtractedRow[] = [];
  const byLabel = new Map(grades.map((g) => [g.label.toUpperCase(), g] as const));

  for (const f of result.fuel) {
    const grade = byLabel.get(f.gradeLabel.toUpperCase());
    if (!grade) continue;
    const cur = sales.fuel.find((r) => r.gradeId === grade.id);
    if (f.salesCAD != null) {
      rows.push({
        key: `fuel:${grade.id}:sales`,
        label: `${grade.label} sales $`,
        scanned: f.salesCAD,
        current: cur?.bullochSalesCAD || undefined,
        apply: (s) => patchFuel(s, grade.id, { bullochSalesCAD: f.salesCAD! }),
      });
    }
    if (f.volumeL != null) {
      rows.push({
        key: `fuel:${grade.id}:vol`,
        label: `${grade.label} volume L`,
        scanned: f.volumeL,
        current: cur?.bullochVolumeL || undefined,
        apply: (s) => patchFuel(s, grade.id, { bullochVolumeL: f.volumeL! }),
      });
    }
  }

  const storeFields: Array<[keyof ScanResult["store"], string]> = [
    ["generalCAD", "General store $"],
    ["tobaccoCAD", "Tobacco $"],
    ["alcoholCAD", "Alcohol $"],
    ["lotteryInCAD", "Lottery in $"],
    ["lotteryOutCAD", "Lottery payout $"],
    ["otherCAD", "Other $"],
  ];
  for (const [key, label] of storeFields) {
    const v = result.store[key];
    if (v == null) continue;
    rows.push({
      key: `store:${key}`,
      label,
      scanned: v,
      current: sales.store[key] || undefined,
      apply: (s) => ({ ...s, store: { ...s.store, [key]: v } }),
    });
  }

  if (result.card.debitCAD != null) {
    rows.push({
      key: "card:debit",
      label: "Debit $",
      scanned: result.card.debitCAD,
      current: sales.card.debitCAD || undefined,
      apply: (s) => ({ ...s, card: { ...s.card, debitCAD: result.card.debitCAD! } }),
    });
  }
  if (result.card.creditCAD != null) {
    rows.push({
      key: "card:credit",
      label: "Credit $",
      scanned: result.card.creditCAD,
      current: sales.card.creditCAD || undefined,
      apply: (s) => ({ ...s, card: { ...s.card, creditCAD: result.card.creditCAD! } }),
    });
  }
  if (result.bankDepositCAD != null) {
    rows.push({
      key: "deposit",
      label: "Bank deposit $",
      scanned: result.bankDepositCAD,
      current: sales.bankDepositCAD || undefined,
      apply: (s) => ({ ...s, bankDepositCAD: result.bankDepositCAD! }),
    });
  }
  if (result.cashFloatCAD != null) {
    rows.push({
      key: "float",
      label: "Cash float $",
      scanned: result.cashFloatCAD,
      current: sales.cashFloatCAD || undefined,
      apply: (s) => ({ ...s, cashFloatCAD: result.cashFloatCAD! }),
    });
  }
  return rows;
}

function patchFuel(s: SalesFile, gradeId: string, patch: Partial<SalesFile["fuel"][number]>): SalesFile {
  const idx = s.fuel.findIndex((f) => f.gradeId === gradeId);
  const next = [...s.fuel];
  if (idx >= 0) next[idx] = { ...next[idx], ...patch };
  else next.push({ gradeId, bullochSalesCAD: 0, bullochVolumeL: 0, ...patch });
  return { ...s, fuel: next };
}

interface Props {
  sales: SalesFile;
  grades: FuelGrade[];
  username: string;
  onApply: (updater: (s: SalesFile) => SalesFile) => void;
}

export function EodScanCard({ sales, grades, username, onApply }: Props) {
  const [available, setAvailable] = useState<boolean | null>(null);
  const [busy, setBusy] = useState(false);
  const [result, setResult] = useState<ScanResult | null>(null);
  const [rows, setRows] = useState<ExtractedRow[]>([]);
  const [checked, setChecked] = useState<Record<string, boolean>>({});
  const [photo, setPhoto] = useState<string | null>(null);

  // Feature-detect once per mount: a 400 (missing body) means the endpoint
  // exists; a 501 means the worker has no Gemini key — hide the card.
  useEffect(() => {
    let cancelled = false;
    api
      .scanEod("", [])
      .then(() => !cancelled && setAvailable(true))
      .catch((err) => {
        if (cancelled) return;
        setAvailable(!(err instanceof ApiError && (err.status === 501 || err.status === 404)));
      });
    return () => {
      cancelled = true;
    };
  }, []);

  async function handleFile(file: File | null) {
    if (!file || !file.type.startsWith("image/")) return;
    setBusy(true);
    setResult(null);
    try {
      const dataUrl = await toScanDataUrl(file);
      setPhoto(dataUrl);
      const res = await api.scanEod(dataUrl, grades.map((g) => g.label));
      const extracted = collectRows(res.result, sales, grades);
      setResult(res.result);
      setRows(extracted);
      setChecked(Object.fromEntries(extracted.map((r) => [r.key, true])));
      if (extracted.length === 0) {
        toast.warning("No usable values found — try a sharper, closer photo.");
      }
    } catch (err) {
      toast.error(err instanceof Error ? err.message : "Scan failed");
    } finally {
      setBusy(false);
    }
  }

  function applyChecked() {
    const chosen = rows.filter((r) => checked[r.key]);
    if (chosen.length === 0) return;
    onApply((s) => {
      let next = chosen.reduce((acc, r) => r.apply(acc), s);
      // keep the scanned photo as evidence alongside the report
      if (photo) {
        const attachment: ReceiptAttachment = {
          id: crypto.randomUUID(),
          name: "eod-scan.jpg",
          dataUrl: photo,
          mimeType: "image/jpeg",
          sizeBytes: Math.round((photo.length * 3) / 4),
          addedAt: new Date().toISOString(),
          addedBy: username,
        };
        next = { ...next, receipts: [...(next.receipts ?? []), attachment] };
      }
      return next;
    });
    toast.success(`Filled ${chosen.length} field(s) from the scan — review before saving.`);
    setResult(null);
    setRows([]);
    setPhoto(null);
  }

  if (available === false) return null;

  return (
    <Card className="border-teal-500/25">
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <ScanLine className="h-4 w-4 text-teal-500" /> Scan the report
        </CardTitle>
        <CardDescription>
          Photograph the Bulloch end-of-day tape and the values below fill themselves. You approve
          every number before it lands in the form — the photo is attached as the day&apos;s receipt.
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="flex flex-wrap items-center gap-2">
          <label>
            <input
              type="file"
              accept="image/*"
              capture="environment"
              className="hidden"
              disabled={busy}
              onChange={(e) => {
                handleFile(e.target.files?.[0] ?? null);
                e.target.value = "";
              }}
            />
            <Button variant="default" disabled={busy} asChild>
              <span className="cursor-pointer">
                {busy ? <Loader2 className="h-4 w-4 animate-spin" /> : <ScanLine className="h-4 w-4" />}
                {busy ? "Reading…" : "Scan with camera"}
              </span>
            </Button>
          </label>
          <label>
            <input
              type="file"
              accept="image/*"
              className="hidden"
              disabled={busy}
              onChange={(e) => {
                handleFile(e.target.files?.[0] ?? null);
                e.target.value = "";
              }}
            />
            <Button variant="outline" disabled={busy} asChild>
              <span className="cursor-pointer">Choose a photo</span>
            </Button>
          </label>
        </div>

        {result ? (
          <div className="space-y-3">
            {result.caveats.length > 0 ? (
              <div className="flex items-start gap-2 rounded-md border border-amber-400/40 bg-amber-50/40 p-3 text-xs dark:bg-amber-950/20">
                <AlertTriangle className="mt-0.5 h-3.5 w-3.5 shrink-0 text-amber-600 dark:text-amber-400" />
                <ul className="space-y-0.5 text-muted-foreground">
                  {result.caveats.map((c, i) => (
                    <li key={i}>{c}</li>
                  ))}
                </ul>
              </div>
            ) : null}
            {rows.length > 0 ? (
              <>
                <div className="overflow-hidden rounded-md border">
                  {rows.map((r) => {
                    const differs = r.current != null && Math.abs(r.current - r.scanned) > 0.005;
                    return (
                      <label
                        key={r.key}
                        className="flex cursor-pointer items-center gap-3 border-b px-3 py-2 text-sm last:border-b-0 hover:bg-secondary/50"
                      >
                        <input
                          type="checkbox"
                          checked={checked[r.key] ?? false}
                          onChange={(e) =>
                            setChecked((c) => ({ ...c, [r.key]: e.target.checked }))
                          }
                          className="h-4 w-4 accent-teal-500"
                        />
                        <span className="flex-1">{r.label}</span>
                        {differs ? (
                          <Badge
                            variant="secondary"
                            className="border-amber-400/40 text-amber-700 dark:text-amber-300"
                            title={`Form currently has ${r.current}`}
                          >
                            was {r.current}
                          </Badge>
                        ) : null}
                        <span className="number-tabular font-semibold">{r.scanned}</span>
                      </label>
                    );
                  })}
                </div>
                <div className="flex items-center gap-2">
                  <Button onClick={applyChecked}>
                    <Check className="h-4 w-4" /> Apply {rows.filter((r) => checked[r.key]).length}{" "}
                    value(s)
                  </Button>
                  <Button
                    variant="ghost"
                    onClick={() => {
                      setResult(null);
                      setRows([]);
                      setPhoto(null);
                    }}
                  >
                    <X className="h-4 w-4" /> Discard
                  </Button>
                </div>
              </>
            ) : (
              <p className="text-xs text-muted-foreground">
                Nothing legible was extracted from this photo.
              </p>
            )}
          </div>
        ) : null}
      </CardContent>
    </Card>
  );
}
